insert into spells (name, level, school, casting_time, range, verbal, somatic, material, duration, concentration, ritual, classes, description, tags) values
('Fire Bolt', 0, 'evocation', '1 action', '120 feet', true, true, false, 'Instantaneous', false, false, array['Bard', 'Sorcerer', 'Wizard'], 'You hurl a mote of fire at a creature or object you can see within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 fire damage. The spell''s damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).', array['cantrip', 'damage', 'evocation']),
('Guidance', 0, 'divination', '1 action', 'Touch', true, true, false, 'Concentration, up to 1 minute', true, true, array['Cleric', 'Druid'], 'You touch one willing creature within range. Once before the spell ends, the target can roll a d4 and add the number rolled to one ability check of its choice. It can roll the die before or after making the ability check. The spell then ends.', array['cantrip', 'buff', 'divination']),
('Sacred Flame', 0, 'evocation', '1 action', '60 feet', true, false, false, 'Instantaneous', false, false, array['Cleric'], 'Flame-like radiance descends on a creature that you can see within range. The target must succeed on a Dexterity saving throw or take 1d8 radiant damage. The target gains no benefit from cover for this save. The spell''s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).', array['cantrip', 'damage', 'evocation']),
('Eldritch Blast', 0, 'evocation', '1 action', '120 feet', true, true, false, 'Instantaneous', false, false, array['Warlock'], 'A beam of crackling energy springs from your finger toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 force damage. The spell creates more than one beam when you reach higher levels: two beams at 5th level, three beams at 11th level, and four beams at 17th level. You can direct the beams at the same target or at different ones.', array['cantrip', 'damage', 'evocation']),
('Magic Missile', 1, 'evocation', '1 action', '120 feet', true, false, false, 'Instantaneous', false, false, array['Sorcerer', 'Wizard'], 'You create three glowing darts of magical force. Each dart hits a creature of your choice that you can see within range. A dart deals 1d4 + 1 force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several. When you cast this spell using a spell slot of 2nd level or higher, the number of darts increases by one for each slot level above 1st.', array['1st-level', 'damage', 'evocation']),
('Detect Magic', 1, 'divination', '1 action', 'Self', true, false, false, 'Concentration, up to 10 minutes', true, true, array['Bard', 'Cleric', 'Druid', 'Paladin', 'Ranger', 'Sorcerer', 'Wizard'], 'For the spell''s duration, you sense the presence of magic within 30 feet of you. If you sense magic in this way, you can use your action to see a faint aura around any visible creature or object in the area that bears magic, and you learn its school of magic, if any.', array['1st-level', 'utility', 'divination', 'ritual']),
('Shield', 1, 'abjuration', '1 reaction, which you take when you are hit by an attack or targeted by the magic missile spell', 'Self', true, false, false, '1 round', false, false, array['Sorcerer', 'Wizard'], 'An invisible barrier of magical force springs into existence to protect you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from magic missile.', array['1st-level', 'defense', 'abjuration']),
('Cure Wounds', 1, 'evocation', '1 action', 'Touch', true, true, false, 'Instantaneous', false, false, array['Bard', 'Cleric', 'Druid'], 'A creature you touch regains a number of hit points equal to 1d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs. When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d8 for each slot level above 1st.', array['1st-level', 'healing', 'evocation']),
('Healing Word', 1, 'evocation', '1 bonus action', '60 feet', true, false, false, 'Instantaneous', false, false, array['Bard', 'Cleric', 'Druid'], 'A creature of your choice that you can see within range regains hit points equal to 1d4 + your spellcasting ability modifier. When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d4 for each slot level above 1st.', array['1st-level', 'healing', 'evocation']),
('Mage Armor', 1, 'abjuration', '1 action', 'Touch', true, true, true, '8 hours', false, false, array['Sorcerer', 'Wizard'], 'You touch a willing creature who isn''t wearing armor, and a protective magical force surrounds it. Until the spell ends, the target''s base AC becomes 13 + its Dexterity modifier. The spell ends if the target dons armor or if you dismiss the spell as an action.', array['1st-level', 'defense', 'abjuration']),
('Sleep', 1, 'enchantment', '1 action', '90 feet', true, false, false, '1 minute', false, false, array['Bard', 'Sorcerer', 'Wizard'], 'This spell sends creatures into a magical slumber. Roll 5d8; the total is how many hit points of creatures this spell can affect. Creatures within 20 feet of a point of your choice within range are affected in ascending order of their current hit points (ignoring unconscious creatures).', array['1st-level', 'control', 'enchantment']),
('Identify', 1, 'divination', '1 minute', 'Touch', true, true, true, 'Instantaneous', false, true, array['Bard', 'Cleric', 'Wizard'], 'You choose one object that you must touch throughout the casting of this spell. If it is a magic item or some other magic-imbued object, you learn its properties and how to use them, whether it requires attunement to use, and how many charges it has if it is a charged item. You learn whether any spells are affecting the item and what they are.', array['1st-level', 'utility', 'divination', 'ritual']),
('Thunderwave', 1, 'evocation', '1 action', 'Self (15-foot cube)', true, true, false, 'Instantaneous', false, false, array['Bard', 'Druid', 'Sorcerer', 'Wizard'], 'A wave of thunderous force pushes creatures away from you. Each creature in a 15-foot cube originating from you must make a Constitution saving throw. On a failed save, a creature takes 2d8 thunder damage and is pushed 5 feet away from you. On a successful save, the creature takes half as much damage and isn''t pushed.', array['1st-level', 'damage', 'evocation']),
('Bless', 1, 'enchantment', '1 action', '30 feet', true, true, true, 'Concentration, up to 1 minute', true, false, array['Cleric', 'Paladin'], 'You bless up to three creatures of your choice within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target can roll a d4 and add the number rolled to the attack roll or saving throw.', array['1st-level', 'buff', 'enchantment']),
('Command', 1, 'enchantment', '1 action', '60 feet', true, false, false, '1 round', false, false, array['Cleric', 'Paladin'], 'You speak a one-word command to a creature you can see within range. The target must succeed on a Wisdom saving throw or follow the command on its next turn. The spell has no effect if the target is undead, if it doesn''t speak a language, or if your command is directly harmful to it.', array['1st-level', 'control', 'enchantment']),
('Scorching Ray', 2, 'evocation', '1 action', '120 feet', true, true, false, 'Instantaneous', false, false, array['Sorcerer', 'Wizard'], 'Each creature in a line 100 feet long and 5 feet wide must make a Dexterity saving throw. A creature takes 8d6 fire damage on a failed save, or half as much damage on a successful one. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd.', array['2nd-level', 'damage', 'evocation']),
('Fireball', 3, 'evocation', '1 action', '150 feet', true, true, true, 'Instantaneous', false, false, array['Sorcerer', 'Wizard'], 'A bright streak flashes from your pointing finger to a point of your choice within range and then blossoms with a low roar into an explosion of flame. Each creature in a 20-foot-radius sphere centered on that point must make a Dexterity saving throw. A target takes 8d6 fire damage on a failed save, or half as much damage on a successful one. The fire spreads around corners. It ignites flammable objects in the area that aren''t being worn or carried.', array['3rd-level', 'damage', 'evocation']),
('Counterspell', 3, 'abjuration', '1 reaction, which you take when you see a creature within 60 feet of you casting a spell', '60 feet', true, false, false, 'Instantaneous', false, false, array['Sorcerer', 'Wizard'], 'You attempt to interrupt a creature in the process of casting a spell. If the creature is casting a spell of 3rd level or lower, its spell fails and has no effect. If it is casting a spell of 4th level or higher, make an ability check using your spellcasting ability. The DC equals 10 + the spell''s level. On a success, the creature''s spell fails and has no effect.', array['3rd-level', 'control', 'abjuration']),
('Haste', 3, 'transmutation', '1 action', '30 feet', true, true, true, 'Concentration, up to 1 minute', true, false, array['Sorcerer', 'Wizard'], 'Choose a willing creature that you can see within range. Until the spell ends, the target''s speed is doubled, it gains a +2 bonus to AC, it has advantage on Dexterity saving throws, and it gains an additional action on each of its turns in combat. That action can be used only to take the Attack (one weapon attack only), Dash, Disengage, Dodge, or Hide action.', array['3rd-level', 'buff', 'transmutation']),
('Misty Step', 2, 'conjuration', '1 bonus action', 'Self', true, false, false, 'Instantaneous', false, false, array['Bard', 'Sorcerer', 'Wizard'], 'Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space that you can see.', array['2nd-level', 'utility', 'conjuration']),
('Hold Person', 2, 'enchantment', '1 action', '60 feet', true, true, true, 'Concentration, up to 1 minute', true, false, array['Bard', 'Cleric', 'Druid', 'Sorcerer', 'Wizard'], 'Choose a humanoid that you can see within range. The target must succeed on a Wisdom saving throw or be paralyzed for the duration. At the end of each of the target''s turns, it can make another Wisdom saving throw. On a success, the spell ends.', array['2nd-level', 'control', 'enchantment']),
('Invisibility', 2, 'illusion', '1 action', 'Touch', true, true, true, 'Concentration, up to 1 hour', true, false, array['Bard', 'Sorcerer', 'Wizard'], 'A creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target''s person. The spell ends if the target attacks or casts a spell.', array['2nd-level', 'utility', 'illusion']),
('Enhance Ability', 2, 'transmutation', '1 action', 'Touch', true, true, true, 'Concentration, up to 1 hour', true, false, array['Bard', 'Cleric', 'Druid', 'Sorcerer', 'Wizard'], 'You touch a creature and bestow upon it a magical enhancement. Choose one of the following effects; the target gains that effect until the spell ends. Strength, Dexterity, Constitution, Intelligence, Wisdom, or Charisma: advantage on ability checks using the chosen ability.', array['2rd-level', 'buff', 'transmutation']),
('Magic Weapon', 2, 'transmutation', '1 bonus action', 'Touch', true, true, true, 'Concentration, up to 1 hour', true, false, array['Paladin', 'Wizard'], 'You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls.', array['2nd-level', 'buff', 'transmutation']),
('Knock', 2, 'transmutation', '1 action', '60 feet', true, false, false, 'Instantaneous', false, false, array['Bard', 'Sorcerer', 'Wizard'], 'Choose an object that you can see within range. The object can be a door, box, chest, lock, shackles, or anything else that contains a mundane or magical means that prevents access. A target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, you open all of them.', array['2nd-level', 'utility', 'transmutation']),
('Levitate', 2, 'transmutation', '1 action', '60 feet', true, true, true, 'Concentration, up to 10 minutes', true, false, array['Sorcerer', 'Wizard'], 'One creature or loose object of your choice that you can see within range rises vertically, up to 20 feet, and remains suspended there for the duration. The spell can levitate a target that weighs up to 500 pounds. An unwilling creature that succeeds on a Constitution saving throw is unaffected.', array['2nd-level', 'utility', 'transmutation']),
('Heat Metal', 2, 'transmutation', '1 action', '60 feet', true, true, true, 'Concentration, up to 1 minute', true, false, array['Bard', 'Druid', 'Wizard'], 'Choose a manufactured metal object, such as a metal weapon or a suit of heavy or medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in contact with the object takes 2d8 fire damage when you cast the spell. Until the spell ends, you can use a bonus action on each of your subsequent turns to cause this damage again.', array['2nd-level', 'damage', 'transmutation']),
('Spiritual Weapon', 2, 'evocation', '1 bonus action', '60 feet', true, true, false, 'Concentration, up to 1 minute', true, false, array['Cleric'], 'You create a spectral, floating, melee weapon within range that lasts for the duration or until you cast this spell again. When you cast the spell, you can make a melee spell attack against a creature within 5 feet of the weapon. On a hit, the target takes 1d8 force damage, and the weapon moves an additional 5 feet toward the target before the end of this turn.', array['2nd-level', 'damage', 'evocation']);
